SELECT COUNT(*) FROM users as u, posts as p, postHistory as ph, votes as v WHERE u.Id = p.OwnerUserId AND p.Id = v.PostId AND p.Id = ph.PostId AND u.DownVotes>=0 AND u.UpVotes>=0 AND p.Score>=-2 AND p.CommentCount<=18 AND p.CreationDate>='2010-07-21 13:50:08'::timestamp AND p.CreationDate<='2014-09-11 00:53:10'::timestamp AND ph.CreationDate>='2010-11-27 03:38:45'::timestamp;